// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/paper/PaperBackground.tsx. Edit it there, then run `npm run sync:film`.
import React, { useMemo } from "react";
import { AbsoluteFill, random } from "remotion";
import { palette } from "../theme/palette";

export type PaperStock = "ivory" | "maroon" | "green" | "cream";

const stocks: Record<PaperStock, { base: string; fibre: string; grain: number }> = {
  ivory: { base: palette.ivory, fibre: "#C9B28A", grain: 0.07 },
  cream: { base: palette.cream, fibre: "#B39A6E", grain: 0.08 },
  maroon: { base: palette.maroon, fibre: "#9C3F4C", grain: 0.12 },
  green: { base: palette.green, fibre: "#A3AB88", grain: 0.1 },
};

/**
 * Grain as a small self-contained SVG tile of warm dark specks (normal blending — no blend modes) (filter id is local to the tile document, so it can
 * never collide or go missing). The browser rasterises it once and repeats it — cheap at 4K.
 */
const grainTile = (opacity: number) => {
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='g' x='0' y='0'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='matrix' values='0 0 0 0 0.17  0 0 0 0 0.11  0 0 0 0 0.06  1.7 0 0 0 -0.62'/></filter><rect width='220' height='220' filter='url(%23g)' opacity='${opacity}'/></svg>`;
  return `url("data:image/svg+xml;utf8,${svg}")`;
};

/**
 * Handmade-paper backdrop: flat stock + subtle grain tile + a sprinkle of fibres.
 * Purely a texture — lighting and vignette belong to <SceneLighting>.
 */
export const PaperBackground: React.FC<{
  stock?: PaperStock;
  width?: number;
  height?: number;
  seed?: string;
  fibres?: number;
  /** Grain + fibres only, over whatever is underneath (e.g. a painted sky). */
  textureOnly?: boolean;
}> = ({ stock = "ivory", width = 1080, height = 1920, seed = "paper", fibres = 70, textureOnly = false }) => {
  const s = stocks[stock];
  const paths = useMemo(
    () =>
      new Array(fibres).fill(0).map((_, i) => {
        const x = random(`${seed}-fx-${i}`) * width;
        const y = random(`${seed}-fy-${i}`) * height;
        const len = 8 + random(`${seed}-fl-${i}`) * 16;
        const a = random(`${seed}-fa-${i}`) * Math.PI * 2;
        const bend = (random(`${seed}-fb-${i}`) - 0.5) * 10;
        const x2 = x + Math.cos(a) * len;
        const y2 = y + Math.sin(a) * len;
        return `M${x.toFixed(1)} ${y.toFixed(1)} Q${((x + x2) / 2 + bend).toFixed(1)} ${((y + y2) / 2 - bend).toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}`;
      }),
    [seed, width, height, fibres],
  );

  return (
    <AbsoluteFill style={{ backgroundColor: textureOnly ? undefined : s.base }}>
      <AbsoluteFill
        style={{ backgroundImage: grainTile(Math.min(1, s.grain * 2.2)), backgroundSize: "220px 220px" }}
      />
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        style={{ position: "absolute", inset: 0 }}
      >
        <g stroke={s.fibre} strokeWidth={0.8} fill="none" opacity={0.35} strokeLinecap="round">
          {paths.map((d, i) => (
            <path key={i} d={d} />
          ))}
        </g>
      </svg>
    </AbsoluteFill>
  );
};
